pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount >= 1 ether);
        vm.assume(amount <= 1000 ether);

        uint256 lenBefore = c.TransferLog().History();

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        uint256 lenAfter = c.TransferLog().History();
        assertTrue(lenAfter == lenBefore + 1, "deposit must append one History entry");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        amount = bound(amount, c.MinDeposit(), 1000 ether);
        vm.assume(actor != address(0));

        uint256 lenBefore = log.History().length;

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        uint256 lenAfter = log.History().length;

        assertTrue(
            lenAfter == lenBefore + 1
                && log.History(lenAfter - 1).Sender == actor
                && log.History(lenAfter - 1).Val == amount,
            "a successful Deposit must append one History entry with the caller and amount"
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public { log = new Log(); c = new C(address(log)); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1 ether, type(uint256).max / 2);
        vm.deal(actor, amount);

        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}(abi.encodeWithSignature("Deposit()"));
        assertTrue(ok);

        // General rule: this successful deposit (>= MinDeposit) must have appended
        // a History entry recording Sender == actor and Val == amount.
        (address sender, , uint256 val, ) = log.History(0);
        assertTrue(sender == actor && val == amount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new C(address(lg));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, c.MinDeposit(), 1000 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        // Rule: a completed deposit of >= MinDeposit must record a History entry.
        bool logged;
        try lg.History(0) returns (
            address,
            string memory,
            uint256,
            uint256
        ) {
            logged = true;
        } catch {
            logged = false;
        }
        assertTrue(logged);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        uint md = c.MinDeposit();
        require(address(this).balance >= md);
        c.Deposit{value: md}();
        assert(c.balances(address(this)) == md);
    }
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}
    fallback() external payable {}

    function run(uint amount1, uint amount2) public {
        require(address(this).balance >= amount1 + amount2);
        require(amount1 >= c.MinDeposit());
        require(amount2 >= c.MinDeposit());
        c.Deposit{value: amount1}();
        c.Deposit{value: amount2}();
        assert(c.balances(address(this)) == amount1 + amount2);
    }
}

